async function renderAnnouncements(){try{const d=await api('/api/admin/announcements');let rows=d.announcements||[];const draw=()=>{setContent(`<div class="card"><div class="sectionHead"><div><div class="eyebrow">COMMUNICATIONS</div><h3>Announcements & Orders</h3><p>Target notices to everyone, members, whitelisted users or staff. Require acknowledgement when needed.</p></div><button id="addAnn">ADD NOTICE</button></div>${rows.map((a,i)=>`<section class="opsEditor"><div class="three"><label>Title<input data-a-title="${i}" value="${esc(a.title||'')}"></label><label>Audience<select data-a-aud="${i}">${['all','member','whitelisted','staff'].map(x=>`<option ${x===a.audience?'selected':''}>${x}</option>`).join('')}</select></label><label>Priority<select data-a-pri="${i}">${['info','important','urgent'].map(x=>`<option ${x===a.priority?'selected':''}>${x}</option>`).join('')}</select></label></div><label>Message<textarea data-a-body="${i}" rows="4">${esc(a.body||'')}</textarea></label><div class="toggleList"><label><input type="checkbox" data-a-pub="${i}" ${a.published!==false?'checked':''}> Published</label><label><input type="checkbox" data-a-ack="${i}" ${a.requiresAck?'checked':''}> Require acknowledgement</label></div><small>${(a.acknowledgedBy||[]).length} acknowledgement(s)</small><button class="danger" data-a-del="${i}">DELETE</button></section>`).join('')}<button id="saveAnn">SAVE ANNOUNCEMENTS</button></div>`);$('addAnn').onclick=()=>{rows.unshift({id:'notice-'+Date.now(),title:'New announcement',body:'',audience:'all',priority:'info',published:false,requiresAck:false,createdAt:new Date().toISOString(),acknowledgedBy:[]});draw()};document.querySelectorAll('[data-a-del]').forEach(b=>b.onclick=()=>{rows.splice(+b.dataset.aDel,1);draw()});$('saveAnn').onclick=async()=>{rows.forEach((a,i)=>{a.title=document.querySelector(`[data-a-title="${i}"]`).value.trim();a.audience=document.querySelector(`[data-a-aud="${i}"]`).value;a.priority=document.querySelector(`[data-a-pri="${i}"]`).value;a.body=document.querySelector(`[data-a-body="${i}"]`).value.trim();a.published=document.querySelector(`[data-a-pub="${i}"]`).checked;a.requiresAck=document.querySelector(`[data-a-ack="${i}"]`).checked});await api('/api/admin/announcements',{method:'POST',body:JSON.stringify({announcements:rows})});notify('Announcements saved');renderAnnouncements()}};draw()}catch(e){errorView('Announcements',e)}}
async function renderGuides(){try{const [d,dc]=await Promise.all([api('/api/admin/guides'),api('/api/admin/discord/channels').catch(()=>({channels:[]}))]);let rows=d.guides||[],channels=dc.channels||[],selected=0;const draw=()=>{const g=rows[selected]||null;setContent(`<div class="card v50Shell"><div class="sectionHead"><div><div class="eyebrow">KNOWLEDGE & DISCORD PUBLISHING</div><h3>Rules, SOPs & How-to Guides</h3><p>Write once in Guardian, publish to the website, and optionally send the same content to a chosen Discord channel as a formatted embed.</p></div><button id="addGuide">ADD PAGE</button></div><div class="v50EditorSplit"><aside class="v50List">${rows.map((x,i)=>`<button class="${i===selected?'active':''}" data-guide-select="${i}"><b>${esc(x.title||'Untitled')}</b><small>${esc(x.category||'Guide')} · ${x.published!==false?'Published':'Draft'}</small></button>`).join('')||'<div class="emptyState">No guide pages yet.</div>'}</aside><section class="v50Editor">${g?`<div class="formGrid"><label>Title<input id="gTitle" value="${esc(g.title||'')}"></label><label>Category<input id="gCat" value="${esc(g.category||'Guides')}"></label><label>Audience<select id="gAud">${['all','member','whitelisted','staff'].map(x=>`<option ${x===g.audience?'selected':''}>${x}</option>`).join('')}</select></label><label>Order<input id="gOrder" type="number" value="${Number(g.order||0)}"></label><label class="wide">Summary<input id="gSummary" value="${esc(g.summary||'')}"></label><label class="wide">Content / Markdown<textarea id="gBody" rows="18">${esc(g.body||'')}</textarea></label></div><div class="v50PublishRow"><label><input id="gPublished" type="checkbox" ${g.published!==false?'checked':''}> Published on Guardian</label><select id="gDiscord"><option value="">Choose Discord channel…</option>${channels.map(c=>`<option value="${esc(c.id)}" ${c.id===g.discordChannelId?'selected':''}># ${esc(c.name)}</option>`).join('')}</select><button id="sendGuideDiscord">SEND TO DISCORD</button><button class="danger" id="deleteGuide">DELETE</button></div>`:'<div class="emptyState">Select or add a guide.</div>'}</section></div><div class="saveBar compact"><span>Discord publishing is optional and does not replace the web copy.</span><button id="saveGuides">SAVE KNOWLEDGE BASE</button></div></div>`);document.querySelectorAll('[data-guide-select]').forEach(b=>b.onclick=()=>{selected=+b.dataset.guideSelect;draw()});$('addGuide').onclick=()=>{rows.push({id:'guide-'+Date.now(),title:'New Guide',category:'Guides',summary:'',body:'# New Guide\n\nStart writing here.',audience:'member',published:false,order:rows.length+1,discordChannelId:''});selected=rows.length-1;draw()};if(g){const sync=()=>{g.title=$('gTitle').value.trim();g.category=$('gCat').value.trim();g.audience=$('gAud').value;g.order=Number($('gOrder').value||0);g.summary=$('gSummary').value.trim();g.body=$('gBody').value;g.published=$('gPublished').checked;g.discordChannelId=$('gDiscord').value};$('deleteGuide').onclick=()=>{if(confirm('Delete this guide?')){rows.splice(selected,1);selected=Math.max(0,selected-1);draw()}};$('sendGuideDiscord').onclick=async()=>{sync();if(!g.discordChannelId)return alert('Choose a Discord channel first');await api('/api/admin/guides/'+encodeURIComponent(g.id)+'/discord',{method:'POST',body:JSON.stringify({guide:g,channelId:g.discordChannelId})});notify('Guide sent to Discord')}}$('saveGuides').onclick=async()=>{if(g){g.title=$('gTitle').value.trim();g.category=$('gCat').value.trim();g.audience=$('gAud').value;g.order=Number($('gOrder').value||0);g.summary=$('gSummary').value.trim();g.body=$('gBody').value;g.published=$('gPublished').checked;g.discordChannelId=$('gDiscord').value}await api('/api/admin/guides',{method:'POST',body:JSON.stringify({guides:rows})});notify('Knowledge base saved');renderGuides()}};draw()}catch(e){errorView('Rules & Guides',e)}}

async function renderTraining(){try{const d=await api('/api/admin/training');let sessions=d.sessions||[],services=d.services||[];setContent(`<div class="card"><div class="sectionHead"><div><div class="eyebrow">TRAINING</div><h3>Training & Qualifications</h3><p>Create sessions, take bookings and award qualifications to attendees.</p></div><button id="addTraining">NEW TRAINING</button></div>${sessions.map(t=>`<section class="opsEditor"><div class="sectionHead"><div><h3>${esc(t.title)}</h3><p>${esc(t.startsAt||'TBC')} · ${esc(t.location||'Location TBC')} · ${(t.bookings||[]).length} booked</p></div><div><button data-t-edit="${t.id}">EDIT</button> <button data-t-complete="${t.id}">COMPLETE / AWARD</button></div></div><p>${esc(t.description||'')}</p><small>Qualification: ${esc(t.qualificationAwarded||'None')}</small></section>`).join('')||'<p>No training sessions yet.</p>'}</div>`);const edit=async(t={})=>{const title=prompt('Training title',t.title||'Training Session');if(!title)return;const startsAt=prompt('Start date/time',t.startsAt||'')||'';const location=prompt('Location',t.location||'')||'';const serviceId=prompt('Service ID',t.serviceId||services[0]?.id||'fire')||'fire';const instructor=prompt('Instructor',t.instructor||'')||'';const qualificationAwarded=prompt('Qualification awarded on completion',t.qualificationAwarded||'')||'';const description=prompt('Description',t.description||'')||'';await api('/api/admin/training',{method:'POST',body:JSON.stringify({session:{...t,title,startsAt,location,serviceId,instructor,qualificationAwarded,description,published:true,announce:confirm('Post to Discord if configured?')}})});notify('Training saved');renderTraining()};$('addTraining').onclick=()=>edit();document.querySelectorAll('[data-t-edit]').forEach(b=>b.onclick=()=>edit(sessions.find(x=>x.id===b.dataset.tEdit)||{}));document.querySelectorAll('[data-t-complete]').forEach(b=>b.onclick=async()=>{if(!confirm('Award the configured qualification to all booked attendees?'))return;await api('/api/admin/training/'+b.dataset.tComplete+'/complete',{method:'POST',body:'{}'});notify('Training completed and qualifications awarded');renderTraining()})}catch(e){errorView('Training',e)}}
async function renderFleet(){try{const d=await api('/api/admin/fleet');let fleet=d.fleet||[];const draw=()=>{setContent(`<div class="card"><div class="sectionHead"><div><div class="eyebrow">FLEET</div><h3>Vehicles & Appliances</h3><p>Manage fire appliances, police units, specialist vehicles and future ambulance assets.</p></div><button id="addFleet">ADD VEHICLE</button></div><div class="tableWrap"><table><thead><tr><th>Service</th><th>Callsign</th><th>Name / Type</th><th>Station / Division</th><th>Status</th><th></th></tr></thead><tbody>${fleet.map((v,i)=>`<tr><td><input data-v-service="${i}" value="${esc(v.serviceId||'')}"></td><td><input data-v-cs="${i}" value="${esc(v.callsign||'')}"></td><td><input data-v-name="${i}" value="${esc(v.name||v.type||'')}"></td><td><input data-v-station="${i}" value="${esc(v.station||'')}"></td><td><select data-v-status="${i}">${['available','deployed','maintenance','off-run'].map(x=>`<option ${x===v.status?'selected':''}>${x}</option>`).join('')}</select></td><td><button class="danger" data-v-del="${i}">×</button></td></tr>`).join('')}</tbody></table></div><button id="saveFleet">SAVE FLEET</button></div>`);$('addFleet').onclick=()=>{fleet.push({id:'vehicle-'+Date.now(),serviceId:'fire',callsign:'',name:'New Vehicle',station:'',status:'available',active:true});draw()};document.querySelectorAll('[data-v-del]').forEach(b=>b.onclick=()=>{fleet.splice(+b.dataset.vDel,1);draw()});$('saveFleet').onclick=async()=>{fleet.forEach((v,i)=>{v.serviceId=document.querySelector(`[data-v-service="${i}"]`).value.trim();v.callsign=document.querySelector(`[data-v-cs="${i}"]`).value.trim().toUpperCase();v.name=document.querySelector(`[data-v-name="${i}"]`).value.trim();v.station=document.querySelector(`[data-v-station="${i}"]`).value.trim();v.status=document.querySelector(`[data-v-status="${i}"]`).value});await api('/api/admin/fleet',{method:'POST',body:JSON.stringify({fleet})});notify('Fleet saved');renderFleet()}};draw()}catch(e){errorView('Fleet',e)}}
async function renderPermissions(){try{const d=await api('/api/admin/role-permissions');let perms=d.permissions||{};const keys=['portal','mdt','control','radio','forms','patrols','training','staff','settings'];const roles=Object.keys(perms);setContent(`<div class="card"><div class="sectionHead"><div><div class="eyebrow">ACCESS CONTROL</div><h3>Roles & Permissions</h3><p>Choose exactly which Guardian modules each account role can use.</p></div><button id="addRole">ADD ROLE</button></div><div class="tableWrap"><table><thead><tr><th>Role</th>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody id="permRows">${roles.map(r=>`<tr><td><b>${esc(r)}</b></td>${keys.map(k=>`<td><input type="checkbox" data-perm="${esc(r)}:${k}" ${perms[r]?.[k]!==false?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><button id="savePerms">SAVE PERMISSIONS</button></div>`);$('addRole').onclick=()=>{const r=(prompt('New role ID (e.g. trainer)')||'').trim().toLowerCase();if(!r||perms[r])return;perms[r]={portal:true,mdt:true,control:false,radio:true,forms:true,patrols:true,training:true,staff:false,settings:false};renderPermissions()};$('savePerms').onclick=async()=>{document.querySelectorAll('[data-perm]').forEach(el=>{const [r,k]=el.dataset.perm.split(':');perms[r]=perms[r]||{};perms[r][k]=el.checked});await api('/api/admin/role-permissions',{method:'POST',body:JSON.stringify({permissions:perms})});notify('Role permissions saved');renderPermissions()}}catch(e){errorView('Roles & Permissions',e)}}



// ============================================================
// Guardian v49 - Admin Suite UX overhaul
// ============================================================
function v49Tabs(items,activeId){return `<div class="settingsSubtabs" role="tablist">${items.map(x=>`<button type="button" class="settingsSubtab ${x.id===activeId?'active':''}" data-v49-tab="${esc(x.id)}">${esc(x.label)}<small>${esc(x.help||'')}</small></button>`).join('')}</div>`}
function v49ListEditor(title,items,kind,help=''){return `<div class="v49List"><div class="v49ListHead"><div><b>${esc(title)}</b>${help?`<small>${esc(help)}</small>`:''}</div><button type="button" data-v49-add-list="${esc(kind)}">+ ADD</button></div><div data-v49-list="${esc(kind)}">${(items||[]).map((x,i)=>`<div class="v49ListRow"><input value="${esc(typeof x==='string'?x:x.name||'')}" data-v49-item="${esc(kind)}:${i}"><button class="danger iconBtn" type="button" data-v49-del-item="${esc(kind)}:${i}" aria-label="Remove">×</button></div>`).join('')||'<div class="emptyState">Nothing added yet.</div>'}</div></div>`}

renderServices=async function(){
 try{const d=await api('/api/admin/services');let services=d.services||[],tab='services',selected=0;
 const draw=()=>{const svc=services[selected]||services[0];if(!svc){setContent(`<div class="card"><div class="sectionHead"><div><div class="eyebrow">MULTI-SERVICE DIRECTORY</div><h3>Services</h3></div><button id="v49AddService">ADD SERVICE</button></div><div class="emptyState">No services configured.</div></div>`);$('v49AddService').onclick=()=>{services.push({id:'service-'+Date.now(),name:'New Service',enabled:true,callsignPattern:'UNIT-##',ranks:[],divisions:[],roles:[],qualifications:[]});selected=services.length-1;draw()};return}
 const tabs=[{id:'services',label:'Services',help:'Identity & divisions'},{id:'ranks',label:'Ranks & Roles',help:'Hierarchy & duties'},{id:'callsigns',label:'Callsigns & Skills',help:'Patterns & qualifications'}];
 const selector=`<div class="serviceSelector">${services.map((s,i)=>`<button class="serviceChip ${i===selected?'active':''}" data-v49-service="${i}"><span>${esc(s.name)}</span><small>${esc(s.id)} · ${s.enabled!==false?'ENABLED':'DISABLED'}</small></button>`).join('')}<button class="serviceChip add" id="v49AddService">+ ADD SERVICE</button></div>`;
 let body='';
 if(tab==='services')body=`<div class="v49PanelGrid"><section class="card inner"><div class="eyebrow">SERVICE IDENTITY</div><h3>${esc(svc.name)}</h3><label>Service name<input id="v49SvcName" value="${esc(svc.name||'')}"></label><label>Service ID<input id="v49SvcId" value="${esc(svc.id||'')}"><small>Used internally. Keep this short and stable.</small></label><div class="toggleCard"><label><input type="checkbox" id="v49SvcEnabled" ${svc.enabled!==false?'checked':''}> Service enabled</label><span>Disabled services remain configured but are hidden from normal users.</span></div></section><section class="card inner">${v49ListEditor('Divisions / Stations / Departments',svc.divisions,'divisions','Examples: Response, Roads Policing, East Scotland / L&B')}</section></div>`;
 if(tab==='ranks')body=`<div class="v49PanelGrid"><section class="card inner">${v49ListEditor('Rank hierarchy',svc.ranks,'ranks','Put highest/most senior rank at the top.')}</section><section class="card inner">${v49ListEditor('Operational roles',svc.roles,'roles','Duties such as Driver, OIC, Dispatcher, Traffic Officer.')}</section></div>`;
 if(tab==='callsigns')body=`<div class="v49PanelGrid"><section class="card inner"><div class="eyebrow">CALLSIGN RULES</div><h3>Callsign configuration</h3><label>Callsign pattern<input id="v49CallsignPattern" value="${esc(svc.callsignPattern||'')}"></label><div class="helpPanel"><b>Pattern examples</b><span><code>J##P#</code> → J27P6</span><span><code>SIERRA-##</code> → SIERRA-21</span><span><code>CONTROL</code> → fixed callsign</span></div></section><section class="card inner">${v49ListEditor('Legacy service skills',svc.qualifications,'qualifications','Quick service list. Use Training → Qualification Library for detailed qualifications, expiry and prerequisites.')}</section></div>`;
 setContent(`<div class="card v49Shell"><div class="sectionHead"><div><div class="eyebrow">MULTI-SERVICE DIRECTORY</div><h3>Services, Ranks, Callsigns & Skills</h3><p>Manage each service in focused sections instead of one long configuration form.</p></div><button id="v49SaveServices">SAVE CHANGES</button></div>${selector}${v49Tabs(tabs,tab)}${body}<div class="dangerZone"><div><b>Remove service</b><small>Only use this when the service should no longer exist anywhere in Guardian.</small></div><button class="danger" id="v49DeleteService">DELETE ${esc(svc.name).toUpperCase()}</button></div></div>`);
 document.querySelectorAll('[data-v49-service]').forEach(b=>b.onclick=()=>{selected=+b.dataset.v49Service;draw()});document.querySelectorAll('[data-v49-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.v49Tab;draw()});
 $('v49AddService').onclick=()=>{services.push({id:'service-'+Date.now(),name:'New Service',enabled:true,callsignPattern:'UNIT-##',ranks:[],divisions:[],roles:[],qualifications:[]});selected=services.length-1;tab='services';draw()};
 const lists={divisions:svc.divisions=svc.divisions||[],ranks:svc.ranks=svc.ranks||[],roles:svc.roles=svc.roles||[],qualifications:svc.qualifications=svc.qualifications||[]};
 document.querySelectorAll('[data-v49-add-list]').forEach(b=>b.onclick=()=>{lists[b.dataset.v49AddList].push('New item');draw()});document.querySelectorAll('[data-v49-del-item]').forEach(b=>b.onclick=()=>{const[k,i]=b.dataset.v49DelItem.split(':');lists[k].splice(+i,1);draw()});
 const collect=()=>{if($('v49SvcName'))svc.name=$('v49SvcName').value.trim();if($('v49SvcId'))svc.id=$('v49SvcId').value.trim().toLowerCase().replace(/[^a-z0-9_-]+/g,'-');if($('v49SvcEnabled'))svc.enabled=$('v49SvcEnabled').checked;if($('v49CallsignPattern'))svc.callsignPattern=$('v49CallsignPattern').value.trim().toUpperCase();document.querySelectorAll('[data-v49-item]').forEach(el=>{const[k,i]=el.dataset.v49Item.split(':');lists[k][+i]=el.value.trim()})};
 $('v49SaveServices').onclick=async()=>{collect();await api('/api/admin/services',{method:'POST',body:JSON.stringify({services})});notify('Service directory saved');renderServices()};$('v49DeleteService').onclick=async()=>{if(!confirm(`Delete ${svc.name}? This cannot be undone.`))return;services.splice(selected,1);selected=Math.max(0,selected-1);await api('/api/admin/services',{method:'POST',body:JSON.stringify({services})});notify('Service removed');renderServices()};
 };draw()
 }catch(e){errorView('Services / Ranks / Callsigns',e)}
}

renderPermissions=async function(){
 try{const d=await api('/api/admin/role-permissions');let perms=d.permissions||{};const groups=[{name:'Member Experience',keys:[['portal','Portal'],['forms','Forms'],['patrols','Operations'],['training','Training'],['guides','Guides']]},{name:'Operational Systems',keys:[['mdt','MDT'],['control','Control'],['radio','Radio']]},{name:'Staff Tools',keys:[['staff','Staff tools'],['applications','Applications'],['announcements','Announcements'],['fleet','Fleet'],['qualifications','Qualifications']]},{name:'Administration',keys:[['services','Services'],['users','Users'],['audit','Audit'],['discord','Discord'],['settings','Settings']]}];let selected=Object.keys(perms)[0]||'player';
 const draw=()=>{const roles=Object.keys(perms);if(!perms[selected])selected=roles[0];const p=perms[selected]||{};setContent(`<div class="card v49Shell"><div class="sectionHead"><div><div class="eyebrow">ACCESS CONTROL</div><h3>Role & Permission Designer</h3><p>Build roles around what people actually need. Permissions are grouped so operational access is easy to understand.</p></div><button id="v49AddRole">ADD ROLE</button></div><div class="permissionLayout"><aside class="permissionRoles">${roles.map(r=>`<button class="permissionRole ${r===selected?'active':''}" data-v49-role="${esc(r)}"><b>${esc(r.toUpperCase())}</b><span>${Object.values(perms[r]||{}).filter(Boolean).length} permissions</span></button>`).join('')}</aside><section class="permissionEditor"><div class="permissionHero"><div><div class="eyebrow">EDITING ROLE</div><h2>${esc(selected.toUpperCase())}</h2></div><div class="buttonGroup"><button id="v49AllPerms">SELECT ALL</button><button id="v49ClearPerms">CLEAR NON-PORTAL</button></div></div>${groups.map(g=>`<div class="permissionGroup"><div><b>${esc(g.name)}</b></div><div class="permissionGrid">${g.keys.map(([k,label])=>`<label class="permissionToggle"><input type="checkbox" data-v49-perm="${k}" ${p[k]?'checked':''}><span><b>${esc(label)}</b><small>${k==='settings'?'Can enter and edit Guardian Settings.':k==='control'?'Can open Control Centre.':k==='users'?'Can manage member/user records.':'Enable this capability for the role.'}</small></span></label>`).join('')}</div></div>`).join('')}<div class="saveBar"><div><h3>Permission changes apply at next access check</h3><p>Owner remains unrestricted and cannot be locked out.</p></div><button id="v49SavePerms">SAVE ROLE PERMISSIONS</button></div></section></div></div>`);
 document.querySelectorAll('[data-v49-role]').forEach(b=>b.onclick=()=>{selected=b.dataset.v49Role;draw()});document.querySelectorAll('[data-v49-perm]').forEach(el=>el.onchange=()=>p[el.dataset.v49Perm]=el.checked);$('v49AllPerms').onclick=()=>{groups.flatMap(g=>g.keys).forEach(([k])=>p[k]=true);draw()};$('v49ClearPerms').onclick=()=>{groups.flatMap(g=>g.keys).forEach(([k])=>p[k]=k==='portal');draw()};$('v49AddRole').onclick=()=>{const r=(prompt('Role ID (example: trainer, fire-command, police-supervisor)')||'').trim().toLowerCase().replace(/[^a-z0-9_-]+/g,'-');if(!r||perms[r])return;perms[r]={portal:true,forms:true,patrols:true,training:true,guides:true,mdt:false,control:false,radio:true,staff:false,applications:false,announcements:false,fleet:false,qualifications:false,services:false,users:false,audit:false,discord:false,settings:false};selected=r;draw()};$('v49SavePerms').onclick=async()=>{await api('/api/admin/role-permissions',{method:'POST',body:JSON.stringify({permissions:perms})});notify('Role permissions saved');renderPermissions()};
 };draw()
 }catch(e){errorView('Roles & Permissions',e)}
}

renderUsers=async function(){
 try{const [d,pd,sd,qd]=await Promise.all([api('/api/admin/users'),api('/api/admin/role-permissions'),api('/api/admin/services'),api('/api/admin/qualifications')]);let users=d.users||[],roles=Object.keys(pd.permissions||{}),services=sd.services||[],quals=qd.qualifications||[];let selected=users[0]?.username||'';
 const draw=()=>{const u=users.find(x=>x.username===selected)||users[0];if(!u){setContent('<div class="card"><h3>No users found.</h3></div>');return}const assignments=Array.isArray(u.serviceAssignments)?u.serviceAssignments:[];const userQuals=Array.isArray(u.qualifications)?u.qualifications:[];setContent(`<div class="card v49Shell"><div class="sectionHead"><div><div class="eyebrow">PEOPLE & ACCESS</div><h3>Member Directory</h3><p>Membership, whitelist, role, service identity and qualifications in one place.</p></div><button id="v49CreateUser">CREATE ACCOUNT</button></div><div class="memberLayout"><aside class="memberList"><input id="v49UserSearch" placeholder="Search members…">${users.map(x=>`<button data-v49-user="${esc(x.username)}" class="memberRow ${x.username===u.username?'active':''}"><span class="avatarMini">${esc((x.displayName||x.username).slice(0,1).toUpperCase())}</span><span><b>${esc(x.displayName||x.username)}</b><small>${esc(x.username)} · ${esc(x.role)}</small></span><span class="statusDot ${x.whitelistStatus==='approved'?'ok':x.whitelistStatus==='rejected'?'off':'warn'}"></span></button>`).join('')}</aside><section class="memberEditor"><div class="memberHero"><div class="avatarLarge">${esc((u.displayName||u.username).slice(0,1).toUpperCase())}</div><div><h2>${esc(u.displayName||u.username)}</h2><p>${esc(u.username)} ${u.protected?'· PROTECTED OWNER':''}</p></div></div><div class="formGrid"><label>Display name<input id="v49DisplayName" value="${esc(u.displayName||'')}"></label><label>Guardian role<select id="v49UserRole" ${u.protected?'disabled':''}>${roles.map(r=>`<option ${r===u.role?'selected':''}>${esc(r)}</option>`).join('')}</select></label><label>Membership<select id="v49Membership"><option value="non-member" ${u.membershipType==='non-member'?'selected':''}>Non-member</option><option value="member" ${u.membershipType==='member'?'selected':''}>Member</option></select></label><label>Whitelist<select id="v49Whitelist"><option value="pending" ${u.whitelistStatus==='pending'?'selected':''}>Pending</option><option value="approved" ${u.whitelistStatus==='approved'?'selected':''}>Approved</option><option value="rejected" ${u.whitelistStatus==='rejected'?'selected':''}>Rejected</option></select></label><label class="wide">Discord User ID<input id="v49DiscordUser" value="${esc(u.discordUserId||'')}" placeholder="Optional Discord user ID"></label></div><div class="memberSection"><div class="sectionHead"><div><h3>Service assignments</h3><p>Assign service, rank, division and callsign. Multiple services are supported.</p></div><button id="v49AddAssignment">ADD SERVICE ASSIGNMENT</button></div><div id="v49Assignments">${assignments.map((a,i)=>{const svc=services.find(s=>s.id===a.serviceId)||services[0]||{};return `<div class="assignmentCard"><div class="four"><label>Service<select data-as-service="${i}">${services.map(s=>`<option value="${esc(s.id)}" ${s.id===a.serviceId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Rank<select data-as-rank="${i}">${(svc.ranks||[]).map(x=>`<option ${x===a.rank?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Division<select data-as-div="${i}">${(svc.divisions||[]).map(x=>`<option ${x===a.division?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Callsign<input data-as-call="${i}" value="${esc(a.callsign||'')}"></label></div><button class="danger" data-as-del="${i}">REMOVE ASSIGNMENT</button></div>`}).join('')||'<div class="emptyState">No service assignments yet.</div>'}</div></div><div class="memberSection"><div class="sectionHead"><div><h3>Qualifications & Skills</h3><p>Qualifications can be awarded manually here or automatically from completed training.</p></div><button id="v49AwardQual">AWARD QUALIFICATION</button></div><div class="qualificationPills">${userQuals.map(q=>{const name=typeof q==='string'?q:q.name||q.id;const exp=typeof q==='object'&&q.expiresAt?new Date(q.expiresAt).toLocaleDateString():'';return `<span class="qualificationPill"><b>${esc(name)}</b>${exp?`<small>Expires ${esc(exp)}</small>`:''}<button data-q-revoke="${esc(typeof q==='string'?q:q.id||q.name)}">×</button></span>`}).join('')||'<div class="emptyState">No qualifications awarded.</div>'}</div></div><div class="saveBar"><div><button id="v49ResetPass">RESET PASSWORD</button>${!u.protected?` <button class="danger" id="v49DeleteUser">DELETE ACCOUNT</button>`:''}</div><button id="v49SaveUser">SAVE MEMBER PROFILE</button></div></section></div></div>`);
 document.querySelectorAll('[data-v49-user]').forEach(b=>b.onclick=()=>{selected=b.dataset.v49User;draw()});$('v49UserSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-v49-user]').forEach(b=>b.style.display=b.textContent.toLowerCase().includes(q)?'':'none')};
 $('v49AddAssignment').onclick=()=>{const svc=services[0]||{};assignments.push({serviceId:svc.id||'',rank:svc.ranks?.[0]||'',division:svc.divisions?.[0]||'',callsign:''});u.serviceAssignments=assignments;draw()};document.querySelectorAll('[data-as-del]').forEach(b=>b.onclick=()=>{assignments.splice(+b.dataset.asDel,1);u.serviceAssignments=assignments;draw()});document.querySelectorAll('[data-as-service]').forEach(el=>el.onchange=()=>{const i=+el.dataset.asService,s=services.find(x=>x.id===el.value)||{};assignments[i]={...assignments[i],serviceId:el.value,rank:s.ranks?.[0]||'',division:s.divisions?.[0]||''};u.serviceAssignments=assignments;draw()});
 $('v49SaveUser').onclick=async()=>{assignments.forEach((a,i)=>{a.serviceId=document.querySelector(`[data-as-service="${i}"]`)?.value||a.serviceId;a.rank=document.querySelector(`[data-as-rank="${i}"]`)?.value||'';a.division=document.querySelector(`[data-as-div="${i}"]`)?.value||'';a.callsign=document.querySelector(`[data-as-call="${i}"]`)?.value.trim().toUpperCase()||''});const result=await api('/api/admin/users/'+encodeURIComponent(u.username)+'/access-profile',{method:'POST',body:JSON.stringify({displayName:$('v49DisplayName').value,role:$('v49UserRole')?.value||u.role,membershipType:$('v49Membership').value,whitelistStatus:$('v49Whitelist').value,discordUserId:$('v49DiscordUser').value,serviceAssignments:assignments})});notify('Member profile saved');renderUsers()};
 $('v49AwardQual').onclick=async()=>{const options=quals.filter(q=>q.active!==false);const pick=prompt('Qualification name to award:\n\n'+options.map(q=>q.name).join('\n'));if(!pick)return;const q=options.find(x=>x.name.toLowerCase()===pick.toLowerCase());if(!q)return alert('Qualification not found. Add it in Training → Qualification Library first.');await api('/api/admin/users/'+encodeURIComponent(u.username)+'/qualification-award',{method:'POST',body:JSON.stringify({qualificationId:q.id})});notify('Qualification awarded');renderUsers()};document.querySelectorAll('[data-q-revoke]').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this qualification?'))return;await api('/api/admin/users/'+encodeURIComponent(u.username)+'/qualification-revoke',{method:'POST',body:JSON.stringify({qualificationId:b.dataset.qRevoke})});notify('Qualification revoked');renderUsers()});
 $('v49ResetPass').onclick=async()=>{const pw=prompt('New password (minimum 8 characters)');if(!pw)return;await api('/api/admin/users/'+encodeURIComponent(u.username)+'/password',{method:'POST',body:JSON.stringify({password:pw})});notify('Password updated')};if($('v49DeleteUser'))$('v49DeleteUser').onclick=async()=>{if(!confirm(`Delete ${u.username}?`))return;await api('/api/admin/users/'+encodeURIComponent(u.username),{method:'DELETE'});notify('Account deleted');renderUsers()};$('v49CreateUser').onclick=()=>{const username=prompt('Username');if(!username)return;const displayName=prompt('Display name',username)||username;const password=prompt('Temporary password (8+ characters)');if(!password)return;const role=prompt('Guardian role',roles.includes('player')?'player':roles[0])||'player';api('/api/admin/users',{method:'POST',body:JSON.stringify({username,displayName,password,role})}).then(()=>{notify('Account created');renderUsers()}).catch(e=>alert(e.message))};
 };draw()
 }catch(e){errorView('Users & Access',e)}
}

renderAnnouncements=async function(){
 try{const [d,dc]=await Promise.all([api('/api/admin/announcements'),api('/api/admin/discord/channels').catch(()=>({channels:[]}))]);let rows=d.announcements||[],channels=dc.channels||[];const draw=()=>{setContent(`<div class="card v49Shell"><div class="sectionHead"><div><div class="eyebrow">COMMUNICATIONS CENTRE</div><h3>Announcements & Operational Orders</h3><p>Publish targeted notices on Guardian and optionally mirror individual notices to a chosen Discord channel.</p></div><button id="v49AddAnn">NEW NOTICE</button></div><div class="noticeList">${rows.map((a,i)=>`<article class="noticeEditor priority-${esc(a.priority||'info')}"><div class="noticeTop"><div><span class="priorityBadge">${esc(String(a.priority||'info').toUpperCase())}</span><input class="titleInput" data-a-title="${i}" value="${esc(a.title||'')}"></div><div class="buttonGroup"><button data-a-discord="${i}">SEND TO DISCORD</button><button class="danger" data-a-del="${i}">DELETE</button></div></div><div class="three"><label>Audience<select data-a-aud="${i}">${['all','member','whitelisted','staff'].map(x=>`<option value="${x}" ${x===a.audience?'selected':''}>${x}</option>`).join('')}</select></label><label>Priority<select data-a-pri="${i}">${['info','important','urgent'].map(x=>`<option value="${x}" ${x===a.priority?'selected':''}>${x}</option>`).join('')}</select></label><label>Discord channel<select data-a-channel="${i}"><option value="">— Choose when sending —</option>${channels.map(c=>`<option value="${esc(c.id)}" ${c.id===a.discordChannelId?'selected':''}># ${esc(c.name)}</option>`).join('')}</select></label></div><label>Message<textarea rows="5" data-a-body="${i}">${esc(a.body||'')}</textarea></label><div class="four"><label>Publish from<input type="datetime-local" data-a-start="${i}" value="${esc(a.publishAt||'')}"></label><label>Expires<input type="datetime-local" data-a-exp="${i}" value="${esc(a.expiresAt||'')}"></label><label class="toggleCard compact"><input type="checkbox" data-a-pub="${i}" ${a.published!==false?'checked':''}> Published</label><label class="toggleCard compact"><input type="checkbox" data-a-ack="${i}" ${a.requiresAck?'checked':''}> Require acknowledgement</label></div><div class="noticeMeta"><span>${(a.acknowledgedBy||[]).length} acknowledgement(s)</span>${a.discordSentAt?`<span>Last sent to Discord ${new Date(a.discordSentAt).toLocaleString()}</span>`:''}</div></article>`).join('')||'<div class="emptyState">No announcements yet.</div>'}</div><div class="saveBar"><div><p>Save drafts and portal publishing settings here. Discord send is manual per notice.</p></div><button id="v49SaveAnn">SAVE ANNOUNCEMENTS</button></div></div>`);
 $('v49AddAnn').onclick=()=>{rows.unshift({id:'notice-'+Date.now(),title:'New announcement',body:'',audience:'all',priority:'info',published:false,requiresAck:false,publishAt:'',expiresAt:'',discordChannelId:'',createdAt:new Date().toISOString(),acknowledgedBy:[]});draw()};document.querySelectorAll('[data-a-del]').forEach(b=>b.onclick=()=>{rows.splice(+b.dataset.aDel,1);draw()});const collect=()=>rows.forEach((a,i)=>{a.title=document.querySelector(`[data-a-title="${i}"]`).value.trim();a.audience=document.querySelector(`[data-a-aud="${i}"]`).value;a.priority=document.querySelector(`[data-a-pri="${i}"]`).value;a.discordChannelId=document.querySelector(`[data-a-channel="${i}"]`).value;a.body=document.querySelector(`[data-a-body="${i}"]`).value.trim();a.publishAt=document.querySelector(`[data-a-start="${i}"]`).value;a.expiresAt=document.querySelector(`[data-a-exp="${i}"]`).value;a.published=document.querySelector(`[data-a-pub="${i}"]`).checked;a.requiresAck=document.querySelector(`[data-a-ack="${i}"]`).checked});$('v49SaveAnn').onclick=async()=>{collect();await api('/api/admin/announcements',{method:'POST',body:JSON.stringify({announcements:rows})});notify('Announcements saved');renderAnnouncements()};document.querySelectorAll('[data-a-discord]').forEach(b=>b.onclick=async()=>{collect();const a=rows[+b.dataset.aDiscord];await api('/api/admin/announcements',{method:'POST',body:JSON.stringify({announcements:rows})});if(!a.discordChannelId)return alert('Choose a Discord channel first.');await api('/api/admin/announcements/'+encodeURIComponent(a.id)+'/discord',{method:'POST',body:JSON.stringify({channelId:a.discordChannelId})});notify('Announcement sent to Discord');renderAnnouncements()});
 };draw()
 }catch(e){errorView('Announcements',e)}
}

renderTraining=async function(){
 try{const [td,qd,dc]=await Promise.all([api('/api/admin/training'),api('/api/admin/qualifications'),api('/api/admin/discord/channels').catch(()=>({channels:[]}))]);let sessions=td.sessions||[],services=td.services||[],quals=qd.qualifications||[],users=qd.users||[],channels=dc.channels||[],tab='sessions';const tabs=[{id:'sessions',label:'Training Sessions',help:'Courses & bookings'},{id:'library',label:'Qualification Library',help:'Skills, validity & prerequisites'},{id:'members',label:'Member Qualifications',help:'Award & review'}];
 const draw=()=>{let body='';if(tab==='sessions')body=`<div class="trainingToolbar"><div><h3>Training Sessions</h3><p>Create courses with capacity, prerequisites, qualification awards and optional Discord announcements.</p></div><button id="v49NewTraining">NEW SESSION</button></div><div class="trainingCards">${sessions.map(t=>`<article class="trainingCard"><div class="sectionHead"><div><div class="eyebrow">${esc((services.find(s=>s.id===t.serviceId)||{}).name||t.serviceId||'JOINT')}</div><h3>${esc(t.title)}</h3><p>${esc(t.startsAt||'TBC')} · ${esc(t.location||'Location TBC')}</p></div><span class="statusBadge ${t.completedAt?'ok':'warn'}">${t.completedAt?'COMPLETED':(t.published!==false?'OPEN':'DRAFT')}</span></div><p>${esc(t.description||'No description provided.')}</p><div class="trainingFacts"><span><b>${(t.bookings||[]).length}${t.maxSlots?'/'+t.maxSlots:''}</b> booked</span><span><b>${esc(t.qualificationAwarded||'None')}</b> qualification</span><span><b>${(t.prerequisites||[]).length}</b> prerequisites</span></div><div class="buttonGroup"><button data-t-edit="${t.id}">EDIT</button><button data-t-complete="${t.id}">COMPLETE / AWARD</button></div></article>`).join('')||'<div class="emptyState">No training sessions yet.</div>'}</div>`;
 if(tab==='library')body=`<div class="trainingToolbar"><div><h3>Qualification & Skills Library</h3><p>This is where you add BA, Emergency Response Driving, TPAC, Firearms, HART, command qualifications and any future skill.</p></div><button id="v49AddQual">ADD QUALIFICATION</button></div><div class="qualificationTable">${quals.map((q,i)=>`<div class="qualificationRow"><input data-ql-name="${i}" value="${esc(q.name||'')}" placeholder="Qualification"><select data-ql-service="${i}"><option value="all" ${q.serviceId==='all'?'selected':''}>All services</option>${services.map(s=>`<option value="${esc(s.id)}" ${s.id===q.serviceId?'selected':''}>${esc(s.name)}</option>`).join('')}</select><input data-ql-cat="${i}" value="${esc(q.category||'Operational')}" placeholder="Category"><input type="number" min="0" data-ql-valid="${i}" value="${Number(q.validityMonths||0)}" title="Validity months"><input data-ql-desc="${i}" value="${esc(q.description||'')}" placeholder="Description"><label class="miniToggle"><input type="checkbox" data-ql-active="${i}" ${q.active!==false?'checked':''}> Active</label><button class="danger iconBtn" data-ql-del="${i}">×</button></div>`).join('')||'<div class="emptyState">No qualifications configured.</div>'}</div><div class="helpPanel"><b>Validity</b><span>0 months = does not expire. For expiring qualifications, Guardian records an expiry date when awarded.</span><b>Prerequisites</b><span>Use Training Sessions to require existing qualifications before booking. Detailed prerequisite editing can be extended later without changing member records.</span></div><button id="v49SaveQuals">SAVE QUALIFICATION LIBRARY</button>`;
 if(tab==='members')body=`<div class="trainingToolbar"><div><h3>Member Qualification Register</h3><p>See what each person holds, including expiry dates. Awarding is also available from Users & Access.</p></div></div><div class="memberQualGrid">${users.map(u=>`<article class="card inner"><div class="sectionHead"><div><h3>${esc(u.displayName||u.username)}</h3><p>${esc(u.username)} · ${esc(u.role)}</p></div><button data-mq-award="${esc(u.username)}">AWARD</button></div><div class="qualificationPills">${(u.qualifications||[]).map(q=>{const name=typeof q==='string'?q:q.name||q.id,exp=typeof q==='object'&&q.expiresAt?new Date(q.expiresAt).toLocaleDateString():'';return `<span class="qualificationPill"><b>${esc(name)}</b>${exp?`<small>Expires ${esc(exp)}</small>`:''}</span>`}).join('')||'<small>No qualifications</small>'}</div></article>`).join('')}</div>`;
 setContent(`<div class="card v49Shell"><div class="sectionHead"><div><div class="eyebrow">LEARNING & COMPETENCE</div><h3>Training, Qualifications & Skills</h3><p>Manage the full lifecycle from defining a skill, to running training, to recording a member's competence.</p></div></div>${v49Tabs(tabs,tab)}${body}</div>`);document.querySelectorAll('[data-v49-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.v49Tab;draw()});
 if(tab==='sessions'){const edit=async(t={})=>{const modal=document.createElement('div');modal.className='modalOverlay';modal.innerHTML=`<div class="modalCard"><div class="sectionHead"><div><div class="eyebrow">TRAINING SESSION</div><h3>${t.id?'Edit':'Create'} training</h3></div><button id="tmClose">×</button></div><div class="formGrid"><label>Title<input id="tmTitle" value="${esc(t.title||'')}"></label><label>Service<select id="tmService">${services.map(s=>`<option value="${esc(s.id)}" ${s.id===t.serviceId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Starts<input type="datetime-local" id="tmStart" value="${esc(t.startsAt||'')}"></label><label>Ends<input type="datetime-local" id="tmEnd" value="${esc(t.endsAt||'')}"></label><label>Location<input id="tmLocation" value="${esc(t.location||'')}"></label><label>Instructor<input id="tmInstructor" value="${esc(t.instructor||'')}"></label><label>Capacity<input type="number" id="tmSlots" min="0" value="${Number(t.maxSlots||0)}"></label><label>Booking closes<input type="datetime-local" id="tmCloseAt" value="${esc(t.bookingClosesAt||'')}"></label><label>Qualification awarded<select id="tmQual"><option value="">None</option>${quals.map(q=>`<option value="${esc(q.id)}" ${q.id===t.qualificationId||q.name===t.qualificationAwarded?'selected':''}>${esc(q.name)}</option>`).join('')}</select></label><label>Discord channel<select id="tmDiscord"><option value="">Default briefing channel</option>${channels.map(c=>`<option value="${esc(c.id)}" ${c.id===t.discordChannelId?'selected':''}># ${esc(c.name)}</option>`).join('')}</select></label><label class="wide">Description<textarea id="tmDesc" rows="5">${esc(t.description||'')}</textarea></label><label class="wide">Prerequisite qualifications<select id="tmPrereq" multiple size="5">${quals.map(q=>`<option value="${esc(q.id)}" ${(t.prerequisites||[]).includes(q.id)?'selected':''}>${esc(q.name)}</option>`).join('')}</select></label></div><div class="toggleList"><label><input type="checkbox" id="tmPublished" ${t.published!==false?'checked':''}> Open / published</label><label><input type="checkbox" id="tmAnnounce"> Send Discord announcement when saved</label></div><div class="modalActions"><button id="tmCancel">CANCEL</button><button id="tmSave">SAVE TRAINING</button></div></div>`;document.body.appendChild(modal);const close=()=>modal.remove();$('tmClose').onclick=$('tmCancel').onclick=close;$('tmSave').onclick=async()=>{const q=quals.find(x=>x.id===$('tmQual').value);const session={...t,title:$('tmTitle').value.trim(),serviceId:$('tmService').value,startsAt:$('tmStart').value,endsAt:$('tmEnd').value,location:$('tmLocation').value.trim(),instructor:$('tmInstructor').value.trim(),maxSlots:Number($('tmSlots').value||0),bookingClosesAt:$('tmCloseAt').value,qualificationId:q?.id||'',qualificationAwarded:q?.name||'',discordChannelId:$('tmDiscord').value,description:$('tmDesc').value.trim(),prerequisites:[...$('tmPrereq').selectedOptions].map(o=>o.value),published:$('tmPublished').checked,announce:$('tmAnnounce').checked};await api('/api/admin/training',{method:'POST',body:JSON.stringify({session})});close();notify('Training saved');renderTraining()}};$('v49NewTraining').onclick=()=>edit();document.querySelectorAll('[data-t-edit]').forEach(b=>b.onclick=()=>edit(sessions.find(x=>x.id===b.dataset.tEdit)||{}));document.querySelectorAll('[data-t-complete]').forEach(b=>b.onclick=async()=>{if(!confirm('Complete this training and award its configured qualification to booked attendees?'))return;await api('/api/admin/training/'+b.dataset.tComplete+'/complete',{method:'POST',body:'{}'});notify('Training completed');renderTraining()})}
 if(tab==='library'){$('v49AddQual').onclick=()=>{quals.push({id:'qual-'+Date.now(),name:'New Qualification',serviceId:'all',category:'Operational',description:'',validityMonths:0,requires:[],active:true});draw()};document.querySelectorAll('[data-ql-del]').forEach(b=>b.onclick=()=>{quals.splice(+b.dataset.qlDel,1);draw()});$('v49SaveQuals').onclick=async()=>{quals.forEach((q,i)=>{q.name=document.querySelector(`[data-ql-name="${i}"]`).value.trim();q.serviceId=document.querySelector(`[data-ql-service="${i}"]`).value;q.category=document.querySelector(`[data-ql-cat="${i}"]`).value.trim();q.validityMonths=Number(document.querySelector(`[data-ql-valid="${i}"]`).value||0);q.description=document.querySelector(`[data-ql-desc="${i}"]`).value.trim();q.active=document.querySelector(`[data-ql-active="${i}"]`).checked});await api('/api/admin/qualifications',{method:'POST',body:JSON.stringify({qualifications:quals})});notify('Qualification library saved');renderTraining()}}
 if(tab==='members')document.querySelectorAll('[data-mq-award]').forEach(b=>b.onclick=async()=>{const name=prompt('Qualification to award:\n\n'+quals.filter(q=>q.active!==false).map(q=>q.name).join('\n'));if(!name)return;const q=quals.find(x=>x.name.toLowerCase()===name.toLowerCase());if(!q)return alert('Qualification not found');await api('/api/admin/users/'+encodeURIComponent(b.dataset.mqAward)+'/qualification-award',{method:'POST',body:JSON.stringify({qualificationId:q.id})});notify('Qualification awarded');renderTraining()});
 };draw()
 }catch(e){errorView('Training & Qualifications',e)}
}


