(function guardianV51SearchInit(){
  const wire=()=>{const s=$('globalSearch');if(!s||s.dataset.wired)return;s.dataset.wired='1';let timer=null;s.addEventListener('input',()=>{clearTimeout(timer);const q=s.value.trim();if(q.length<2){document.getElementById('globalSearchPanel')?.remove();return}timer=setTimeout(async()=>{try{const d=await api('/api/admin/search?q='+encodeURIComponent(q));let p=document.getElementById('globalSearchPanel');if(!p){p=document.createElement('div');p.id='globalSearchPanel';p.className='globalSearchPanel';document.body.appendChild(p)}const rows=d.results||[];p.innerHTML=`<div class="searchHead"><b>Search Guardian</b><button id="closeGlobalSearch">×</button></div>${rows.length?rows.map(r=>`<button class="searchResult" data-search-link="${esc(r.link||'')}"><span class="badge">${esc(r.type||'ITEM')}</span><b>${esc(r.title)}</b><small>${esc(r.subtitle||'')}</small></button>`).join(''):'<div class="emptyState">No matching records.</div>'}`;$('closeGlobalSearch').onclick=()=>p.remove();p.querySelectorAll('[data-search-link]').forEach(b=>b.onclick=()=>{if(b.dataset.searchLink)location.href=b.dataset.searchLink;p.remove()})}catch(e){console.warn(e)}},180)});};
  addEventListener('load',wire);setTimeout(wire,400);
})();

function v51Modal(title,body,actions=''){const m=document.createElement('div');m.className='modalOverlay';m.innerHTML=`<div class="modalCard"><div class="sectionHead"><div><div class="eyebrow">GUARDIAN COMMAND SUITE</div><h3>${esc(title)}</h3></div><button data-close-v51>×</button></div>${body}<div class="modalActions">${actions}</div></div>`;document.body.appendChild(m);m.querySelector('[data-close-v51]').onclick=()=>m.remove();return m}

// Service onboarding wizard layered onto the existing v49/v50 service editor.
const _v51BaseRenderServices=renderServices;
renderServices=async function(){
  await _v51BaseRenderServices();
  const host=document.querySelector('#content .sectionHead');if(!host||document.getElementById('v51OnboardService'))return;
  const btn=document.createElement('button');btn.id='v51OnboardService';btn.textContent='ONBOARD SERVICE';btn.className='primaryAction';host.appendChild(btn);
  btn.onclick=()=>{
    const m=v51Modal('Service onboarding wizard',`<div class="stepper"><span class="active">1 Service</span><span>2 Structure</span><span>3 Fleet</span><span>4 Skills</span><span>5 Radio</span></div><div class="formGrid"><label>Service type<select id="owType"><option value="police">Police</option><option value="ambulance">Ambulance / NHS</option><option value="fire">Fire & Rescue</option><option value="specialist">Specialist / SAS</option><option value="control">Control</option></select></label><label>Display name<input id="owName" value="Police"></label><label>Service ID<input id="owId" value="police"></label><label>Accent colour<input id="owAccent" type="color" value="#2f7fd3"></label><label>Callsign format<input id="owCallsign" value="P##"></label><label>Initial division / area<input id="owDivision" value="Response"></label><label>Initial station / base<input id="owStation" value="Central Police Station"></label><label>Initial vehicle type<input id="owVehicle" value="Response Vehicle"></label><label class="wide">Starter ranks<textarea id="owRanks" rows="6">Chief Constable\nDeputy Chief Constable\nAssistant Chief Constable\nSuperintendent\nInspector\nSergeant\nPolice Constable</textarea></label><label class="wide">Starter qualifications<textarea id="owQuals" rows="5">Response Driving\nRoads Policing\nPublic Order\nTaser\nFirearms</textarea></label><label class="wide">Starter radio groups<textarea id="owRadio" rows="4">POL-OPS1\nPOL-OPS2\nPOL-OPS3</textarea></label></div>`,`<button data-close-wizard>CANCEL</button><button id="owCreate">CREATE SERVICE</button>`);
    const sync=()=>{const type=$('owType').value;const defaults={police:['Police','police','#2f7fd3','P##','Response','Central Police Station','Response Vehicle'],ambulance:['Ambulance / NHS','ambulance','#2f9e66','A##','Operations','Ambulance Station','Emergency Ambulance'],fire:['Fire & Rescue','fire','#d84646','J##P#','East Scotland / L&B','Fire Station','Pump'],specialist:['Specialist / SAS','specialist','#6d7280','S##','Specialist Operations','Specialist Base','Specialist Vehicle'],control:['Control','control','#8656c7','CTRL-#','Control','Control Centre','Control Desk']}[type];['owName','owId','owAccent','owCallsign','owDivision','owStation','owVehicle'].forEach((id,i)=>$(id).value=defaults[i])};$('owType').onchange=sync;m.querySelector('[data-close-wizard]').onclick=()=>m.remove();$('owCreate').onclick=async()=>{const payload={service:{id:$('owId').value.trim().toLowerCase(),name:$('owName').value.trim(),accentColor:$('owAccent').value,callsignPattern:$('owCallsign').value.trim(),ranks:$('owRanks').value.split('\n').map(x=>x.trim()).filter(Boolean),divisions:[$('owDivision').value.trim()].filter(Boolean),roles:[],qualifications:$('owQuals').value.split('\n').map(x=>x.trim()).filter(Boolean),starterStation:$('owStation').value.trim(),starterVehicleType:$('owVehicle').value.trim(),radioGroups:$('owRadio').value.split('\n').map(x=>x.trim()).filter(Boolean)}};await api('/api/admin/services/onboard',{method:'POST',body:JSON.stringify(payload)});m.remove();notify('Service onboarded');await refreshAll()};
  };
};

async function renderGovernance(){
  try{const [pd,sv,qd]=await Promise.all([api('/api/admin/personnel'),api('/api/admin/services'),api('/api/admin/qualifications')]);let users=pd.users||[],pathways=pd.promotionPathways||[],services=sv.services||[],quals=qd.qualifications||[],selected=users[0]?.username||'',tab='personnel';
  const tabs=[{id:'personnel',label:'Personnel Files',help:'Notes, history & cross-links'},{id:'discipline',label:'Discipline',help:'Cases, outcomes & actions'},{id:'promotions',label:'Promotion Pathways',help:'Requirements & authority'},{id:'duty',label:'Duty Management',help:'Admin-controlled duty & hours'}];
  const draw=()=>{const u=users.find(x=>x.username===selected)||users[0],svc=services.find(x=>x.id===u?.serviceAssignments?.[0]?.serviceId);let body='';
    if(tab==='personnel')body=`<div class="memberLayout"><aside class="memberList">${users.map(x=>`<button class="memberRow ${x.username===u?.username?'active':''}" data-gov-user="${esc(x.username)}"><span class="avatarMini">${esc((x.displayName||x.username).slice(0,1).toUpperCase())}</span><span><b>${esc(x.displayName||x.username)}</b><small>${esc(x.username)} · ${esc(x.role)}</small></span><i></i></button>`).join('')}</aside><section>${u?`<div class="memberHero"><span class="avatarLarge">${esc((u.displayName||u.username).slice(0,1).toUpperCase())}</span><div><h2>${esc(u.displayName||u.username)}</h2><p>${esc(u.username)} · ${esc(u.role)} · ${esc(u.whitelistStatus||'pending')}</p></div></div><div class="profileLinkGrid"><a href="#patrols">Operations & Patrols</a><a href="#formsbuilder">Forms & Submissions</a><a href="#training">Qualifications & Training</a><a href="#audit">Audit History</a></div><div class="v51Timeline"><h3>Service & promotion history</h3>${(u.personnel?.serviceHistory||[]).concat(u.personnel?.promotionHistory||[]).sort((a,b)=>String(b.at||'').localeCompare(String(a.at||''))).map(x=>`<div><b>${esc(x.title||x.action||'Record')}</b><small>${x.at?new Date(x.at).toLocaleString():'—'} · ${esc(x.by||'SYSTEM')}</small><p>${esc(x.note||'')}</p></div>`).join('')||'<div class="emptyState">No service history recorded yet.</div>'}</div><div class="formGrid"><label class="wide">Private staff notes<textarea id="pfNotes" rows="7">${esc((u.personnel?.notes||[]).map(n=>`[${n.at||''}] ${n.by||''}: ${n.text||''}`).join('\n'))}</textarea></label><label class="wide">Add commendation<input id="pfComm" placeholder="Reason / achievement"></label><label class="wide">Add warning / advisory note<input id="pfWarn" placeholder="Operational or conduct note"></label></div><div class="buttonGroup"><button id="savePersonnelNote">ADD STAFF NOTE</button><button id="addCommendation">ADD COMMENDATION</button><button id="addWarning">ADD WARNING</button></div>`:'<div class="emptyState">No members.</div>'}</section></div>`;
    if(tab==='discipline')body=`<div class="trainingToolbar"><div><h3>Roleplay disciplinary casework</h3><p>Track conduct issues, investigations, outcomes, appeals and expiry without mixing it into public notes.</p></div><button id="newDiscipline">NEW CASE</button></div><div class="trainingCards">${users.flatMap(x=>(x.personnel?.disciplinary||[]).map(c=>({...c,username:x.username,displayName:x.displayName}))).map(c=>`<article class="trainingCard"><div class="sectionHead"><div><div class="eyebrow">${esc((c.status||'open').toUpperCase())}</div><h3>${esc(c.title||'Disciplinary case')}</h3><p>${esc(c.displayName||c.username)} · ${c.openedAt?new Date(c.openedAt).toLocaleDateString():'—'}</p></div><span class="statusBadge ${c.status==='closed'?'ok':'warn'}">${esc(c.status||'open')}</span></div><p>${esc(c.summary||'')}</p><small>Outcome: ${esc(c.outcome||'Pending')}</small></article>`).join('')||'<div class="emptyState">No disciplinary cases.</div>'}</div>`;
    if(tab==='promotions')body=`<div class="trainingToolbar"><div><h3>Promotion pathways & authority</h3><p>Define the minimum hours, qualifications and sign-off required for each target rank. Promotion authority can be capped per service.</p></div><button id="addPathway">ADD PATHWAY</button></div><div class="trainingCards">${pathways.map((p,i)=>`<article class="trainingCard"><div class="formGrid"><label>Service<select data-pw-service="${i}">${services.map(s=>`<option value="${esc(s.id)}" ${s.id===p.serviceId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Target rank<input data-pw-rank="${i}" value="${esc(p.targetRank||'')}"></label><label>Minimum hours<input type="number" min="0" data-pw-hours="${i}" value="${Number(p.minimumHours||0)}"></label><label>Minimum current rank<input data-pw-current="${i}" value="${esc(p.minimumCurrentRank||'')}"></label><label class="wide">Required qualifications<input data-pw-quals="${i}" value="${esc((p.requiredQualifications||[]).join(', '))}" placeholder="Incident Command L1, BA"></label><label class="wide">Approved promoters (usernames, comma separated)<input data-pw-promoters="${i}" value="${esc((p.approvedPromoters||[]).join(', '))}"></label></div><button class="danger" data-pw-del="${i}">DELETE</button></article>`).join('')||'<div class="emptyState">No pathways configured.</div>'}</div><button id="savePathways">SAVE PROMOTION PATHWAYS</button>`;
    if(tab==='duty')body=`<div class="trainingToolbar"><div><h3>Duty management</h3><p>Only authorised staff can place users on/off duty. Hours are written to the personnel file automatically.</p></div></div><div class="tableWrap"><table><thead><tr><th>Member</th><th>Service</th><th>Station / Division</th><th>Role / Rank</th><th>Callsign</th><th>Status</th><th>Action</th></tr></thead><tbody>${users.map(x=>{const a=x.serviceAssignments?.[0]||{},d=x.personnel?.activeDuty;return `<tr><td><b>${esc(x.displayName||x.username)}</b><br><small>${esc(x.username)}</small></td><td>${esc(a.serviceId||'—')}</td><td>${esc(a.division||'—')}</td><td>${esc(a.rank||'—')}</td><td>${esc(a.callsign||'—')}</td><td><span class="statusBadge ${d?'ok':'off'}">${d?'ON DUTY':'OFF DUTY'}</span></td><td>${d?`<button data-duty-off="${esc(x.username)}">BOOK OFF</button>`:`<button data-duty-on="${esc(x.username)}">BOOK ON</button>`}</td></tr>`}).join('')}</tbody></table></div>`;
    setContent(`<div class="card v49Shell"><div class="sectionHead"><div><div class="eyebrow">PEOPLE & GOVERNANCE</div><h3>Personnel, Discipline, Promotions & Duty</h3><p>One controlled place for operational people records. Sensitive actions are audited.</p></div></div>${v49Tabs(tabs,tab)}${body}</div>`);document.querySelectorAll('[data-v49-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.v49Tab;draw()});document.querySelectorAll('[data-gov-user]').forEach(b=>b.onclick=()=>{selected=b.dataset.govUser;draw()});
    if(tab==='personnel'&&u){$('savePersonnelNote').onclick=async()=>{const text=prompt('Staff note');if(!text)return;await api('/api/admin/personnel/'+encodeURIComponent(u.username)+'/note',{method:'POST',body:JSON.stringify({text})});notify('Note added');renderGovernance()};$('addCommendation').onclick=async()=>{const text=$('pfComm').value.trim();if(!text)return;await api('/api/admin/personnel/'+encodeURIComponent(u.username)+'/commendation',{method:'POST',body:JSON.stringify({text})});notify('Commendation added');renderGovernance()};$('addWarning').onclick=async()=>{const text=$('pfWarn').value.trim();if(!text)return;await api('/api/admin/personnel/'+encodeURIComponent(u.username)+'/warning',{method:'POST',body:JSON.stringify({text})});notify('Warning added');renderGovernance()}}
    if(tab==='discipline')$('newDiscipline').onclick=()=>{const username=prompt('Guardian username');if(!username)return;const title=prompt('Case title','Conduct review');if(!title)return;const summary=prompt('Case summary','')||'';api('/api/admin/personnel/'+encodeURIComponent(username)+'/discipline',{method:'POST',body:JSON.stringify({title,summary})}).then(()=>{notify('Disciplinary case opened');renderGovernance()}).catch(e=>alert(e.message))};
    if(tab==='promotions'){$('addPathway').onclick=()=>{pathways.push({id:'path-'+Date.now(),serviceId:services[0]?.id||'fire',targetRank:'',minimumHours:0,minimumCurrentRank:'',requiredQualifications:[],approvedPromoters:[]});draw()};document.querySelectorAll('[data-pw-del]').forEach(b=>b.onclick=()=>{pathways.splice(+b.dataset.pwDel,1);draw()});$('savePathways').onclick=async()=>{pathways.forEach((p,i)=>{p.serviceId=document.querySelector(`[data-pw-service="${i}"]`).value;p.targetRank=document.querySelector(`[data-pw-rank="${i}"]`).value.trim();p.minimumHours=Number(document.querySelector(`[data-pw-hours="${i}"]`).value||0);p.minimumCurrentRank=document.querySelector(`[data-pw-current="${i}"]`).value.trim();p.requiredQualifications=document.querySelector(`[data-pw-quals="${i}"]`).value.split(',').map(x=>x.trim()).filter(Boolean);p.approvedPromoters=document.querySelector(`[data-pw-promoters="${i}"]`).value.split(',').map(x=>x.trim()).filter(Boolean)});await api('/api/admin/promotion-pathways',{method:'POST',body:JSON.stringify({pathways})});notify('Promotion pathways saved');renderGovernance()}}
    if(tab==='duty'){document.querySelectorAll('[data-duty-on]').forEach(b=>b.onclick=async()=>{const username=b.dataset.dutyOn,usr=users.find(x=>x.username===username),a=usr?.serviceAssignments?.[0]||{};const callsign=prompt('Duty callsign',a.callsign||'')||'';await api('/api/admin/personnel/'+encodeURIComponent(username)+'/duty',{method:'POST',body:JSON.stringify({action:'on',serviceId:a.serviceId||'',station:a.division||'',rank:a.rank||'',callsign})});notify('Booked on duty');renderGovernance()});document.querySelectorAll('[data-duty-off]').forEach(b=>b.onclick=async()=>{await api('/api/admin/personnel/'+encodeURIComponent(b.dataset.dutyOff)+'/duty',{method:'POST',body:JSON.stringify({action:'off'})});notify('Booked off duty');renderGovernance()})}
  };draw()}catch(e){errorView('People & Governance',e)}
}

